declare(strict_types=1);
require_once __DIR__.'/finance_service.php';require_once __DIR__.'/invoice_lib.php';require_once __DIR__.'/invoice_archive.php';
function gszCsv(array $headers,array $rows):string {$out="\xEF\xBB\xBF".implode(';',array_map('invCsvCell',$headers))."\r\n";foreach($rows as $row)$out.=implode(';',array_map('invCsvCell',array_values($row)))."\r\n";return $out;}
/** Bounded, dependency-free ZIP (stored), no extraction or user-controlled paths. */
function gszZip(array $files):string {
 if(count($files)>200)throw new RuntimeException('Export maximal 200 Dateien.');$body='';$central='';$count=0;$total=0;foreach($files as $name=>$bytes){if($name===''||str_contains($name,'..')||str_contains($name,"\0")||str_contains($name,'\\')||str_starts_with($name,'/'))throw new RuntimeException('Unsicherer Exportpfad.');$total+=strlen($bytes);if($total>20*1024*1024)throw new RuntimeException('Export maximal 20 MB; Zeitraum verkleinern.');$offset=strlen($body);$size=strlen($bytes);$crc=hexdec(hash('crc32b',$bytes));$body.=pack('VvvvvvVVVvv',0x04034b50,20,0x0800,0,0,33,$crc,$size,$size,strlen($name),0).$name.$bytes;$central.=pack('VvvvvvvVVVvvvvvVV',0x02014b50,20,20,0x0800,0,0,33,$crc,$size,$size,strlen($name),0,0,0,0,0,$offset).$name;$count++;}return $body.$central.pack('VvvvvVVv',0x06054b50,0,0,$count,$count,strlen($central),strlen($body),0);
}
function financeBundle(PDO $pdo,string $from,string $to):array {
 financeSummary($pdo,$from,$to);$q=$pdo->prepare('SELECT p.id,p.paid_on,p.amount_cents,p.tax_cents,p.invoice_id,p.receipt_id,p.bank_transaction_id,p.reversal_of,p.reason FROM finance_payments p WHERE p.paid_on BETWEEN ? AND ? ORDER BY p.paid_on,p.id LIMIT 2001');$q->execute([$from,$to]);$payments=$q->fetchAll();if(count($payments)>2000)throw new RuntimeException('Export maximal 2000 Zahlungszeilen. Zeitraum verkleinern.');$receiptIds=[];$invoiceIds=[];foreach($payments as &$p){if($p['receipt_id'])$receiptIds[(int)$p['receipt_id']]=true;if($p['invoice_id'])$invoiceIds[(int)$p['invoice_id']]=true;$p['amount_cents']=financeDecimal((int)$p['amount_cents']);$p['tax_cents']=financeDecimal((int)$p['tax_cents']);}unset($p);
 $files=['zahlungen.csv'=>gszCsv(['Zahlung-ID','Datum','Betrag EUR','USt-Anteil EUR','Rechnung-ID','Beleg-ID','Bank-ID','Gegenzeile-zu','Korrekturgrund'],$payments)];$q=$pdo->prepare("SELECT r.id,r.number,r.status,r.merchant,r.receipt_date,r.gross_cents,r.category,r.document_id FROM finance_receipts r WHERE r.receipt_date BETWEEN ? AND ? ORDER BY r.id LIMIT 1001");$q->execute([$from,$to]);$receipts=$q->fetchAll();if(count($receipts)>1000)throw new RuntimeException('Beleglimit erreicht. Zeitraum verkleinern.');foreach($receipts as &$r){$receiptIds[(int)$r['id']]=true;$r['gross_cents']=$r['gross_cents']===null?'':financeDecimal((int)$r['gross_cents']);}unset($r);$files['belegpruefliste.csv']=gszCsv(['Beleg-ID','Belegnummer','Status','Haendler','Datum','Brutto EUR','Kategorie','Dokument-ID'],$receipts);
 $q=$pdo->prepare('SELECT t.id,t.booked_on,t.amount_cents,t.currency,t.counterparty,t.purpose FROM bank_transactions t WHERE t.booked_on BETWEEN ? AND ? AND NOT EXISTS(SELECT 1 FROM finance_payments p WHERE p.allocation_key=t.id) ORDER BY t.id LIMIT 2001');$q->execute([$from,$to]);$unmatched=$q->fetchAll();if(count($unmatched)>2000)throw new RuntimeException('Umsatzlimit erreicht.');foreach($unmatched as &$t)$t['amount_cents']=financeDecimal((int)$t['amount_cents']);unset($t);$files['ungeklaerte-umsaetze.csv']=gszCsv(['Umsatz-ID','Datum','Betrag EUR','Waehrung','Gegenpartei','Zweck'],$unmatched);
 $totalBytes=array_sum(array_map('strlen',$files));if(count($receiptIds)+count($invoiceIds)>150||$totalBytes>20*1024*1024)throw new RuntimeException('Exportlimit: Zeitraum verkleinern.');$originals=[];$q=$pdo->prepare('SELECT d.* FROM documents d JOIN finance_receipts r ON r.document_id=d.id WHERE r.id=?');foreach(array_keys($receiptIds) as $id){$q->execute([$id]);$d=$q->fetch();if(!$d||isset($originals[$d['id']]))continue;if(!preg_match('/^[a-f0-9]{32}$/D',$d['stored_name']))throw new RuntimeException('Ungültiger Originalpfad.');$path=documentStorageDir().'/'.$d['stored_name'];if(is_link($path)||!is_file($path)||hash_file('sha256',$path)!==$d['sha256'])throw new RuntimeException('Originalintegrität verletzt; Export gestoppt.');$name='originale/dokument-'.$d['id'].'-'.preg_replace('/[^a-zA-Z0-9._-]/','_',$d['original_name']);if((int)$d['size_bytes']>10*1024*1024||$totalBytes+(int)filesize($path)>20*1024*1024)throw new RuntimeException('Export maximal 20 MB.');$files[$name]=file_get_contents($path);$totalBytes+=strlen($files[$name]);$originals[$d['id']]=true;}
 $q=$pdo->prepare('SELECT * FROM invoices WHERE id=?');foreach(array_keys($invoiceIds) as $id){$q->execute([$id]);$inv=$q->fetch();$bytes=invoiceDocumentPdf($inv,invItems($pdo,$id));$totalBytes+=strlen($bytes);if($totalBytes>20*1024*1024)throw new RuntimeException('Export maximal 20 MB.');$folder=empty($inv['archived_pdf_sha256'])?'rechnungen-technisch':'rechnungen-archiviert';$files[$folder.'/rechnung-'.$id.'.pdf']=$bytes;}
 $hashes=[];foreach($files as $name=>$data)$hashes[]=hash('sha256',$data).'  '.$name;$files['SHA256SUMS.txt']=implode("\n",$hashes)."\n";$files['HINWEISE.txt']="GSZ Steuerberater-Arbeitsexport $from bis $to. Kein DATEV-/GoBD-Nachweis, keine USt-Voranmeldung. Originale unverändert mit Hash. Neue Ausstellungs-PDFs liegen unter rechnungen-archiviert unverändert mit SHA-256. Historische Dokumente ohne Snapshot stehen unter rechnungen-technisch als neu erzeugte Darstellung; sie werden nicht als ursprüngliche Originale ausgewiesen. Prüflisten einschließlich ungeklärter Umsätze beachten. Anlagenzuordnungen/Anschaffung/AfA sind gesondert abzugrenzen; manuelle Anlagenpläne werden nicht automatisch steuerlich verbucht, keine doppelte Berücksichtigung zulässig.\n";return $files;
}
